  ("According to the data, corruption causes great damage to the country every year.", "طبق آمار، فساد هر سال خسارت بزرگی به کشور وارد می‌کند.", "tebgh-e âmâr, fesâd har sâl khesârat-e bozorgi be keshvar vâred mikonad."),
  ("In your opinion, is the law the same for everyone in our country?", "به نظر تو، در کشور ما قانون برای همه یکسان است؟", "be nazar-e to, dar keshvar-e mâ ghânun barâ-ye hame yeksân ast?"),
  ("The family has been demanding justice for more than ten years.", "این خانواده بیش از ده سال است که خواستار عدالت است.", "in khânevâde bish az dah sâl ast ke khâstâr-e edâlat ast."),
  ("Don't call anyone guilty before the court's decision!", "قبل از رأی دادگاه، هیچ‌کس را گناهکار ندان!", "ghabl az ra'y-e dâdgâh, hichkas râ gonâhkâr nadân!"),
  ("The journalist said he had faced censorship for years.", "روزنامه‌نگار گفت سال‌ها با سانسور روبه‌رو بوده است.", "ruznâmenegâr goft sâlhâ bâ sânsur ruberu bude ast."),
